# Industrial automation: read a DHT22 sensor on a Raspberry Pi
# Uses the adafruit-circuitpython-dht library over GPIO pins
import time
import board
import adafruit_dht

# GPIO pins wired to four DHT22 sensors (BCM numbering)
SENSOR_PINS = [board.D4, board.D5, board.D17, board.D23]

def read_dht22(dht_device):
    """Read temperature and humidity from a DHT22 sensor."""
    # Attempt a single reading and return it
    try:
        temperature_c = dht_device.temperature
        humidity_percent = dht_device.humidity
        return temperature_c, humidity_percent
    except RuntimeError as sensor_error:
        # DHT22 sometimes returns invalid data
        print("DHT22 read error:", sensor_error)
        return None, None

def describe_state(temperature_c, humidity_percent):
    """Return a short human-readable state description."""
    # Build a compact status string for the automation log
    if temperature_c is None:
        return "no reading"
    return "temp %.1fC hum %.1f%%" % (temperature_c, humidity_percent)

if __name__ == "__main__":
    # Open each DHT22 sensor in turn
    sensor_devices = []
    try:
        for sensor_pin in SENSOR_PINS:
            sensor_devices.append(adafruit_dht.DHT22(sensor_pin))
        while True:
            # Read every sensor and report its state
            for sensor_index, dht_device in enumerate(sensor_devices):
                temperature_c, humidity_percent = read_dht22(dht_device)
                print("Sensor %d %s" % (sensor_index, describe_state(temperature_c, humidity_percent)))
            time.sleep(60.0)
    except KeyboardInterrupt:
        # Operator stopped the automation loop
        print("DHT22 monitoring stopped")
    finally:
        # Release the DHT22 sensors cleanly
        for dht_device in sensor_devices:
            dht_device.exit()

# temperature/humidity station for a Raspberry Pi using DHT22 sensors
# Reads multiple DHT22 sensors on different GPIO pins using a common driver
import time
import sys
import logging
import board
import adafruit_dht

logging.basicConfig(level=logging.INFO)
LOGGER = logging.getLogger("dht22_station")

# Map of sensor labels to their BCM GPIO pins
SENSOR_PINS = {
    "entryway": board.D4,
    "greenhouse": board.D7,
    "attic": board.D11,
    "basement": board.D17,
}


def read_sensor(dht_device):
    """Read temperature and humidity from one DHT22 sensor."""
    # Attempt a single reading and return it if valid
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is not None and humidity is not None:
            return temperature, humidity
    except RuntimeError as sensor_error:
        LOGGER.error("DHT22 read failed: %s", sensor_error)
    return None, None


def main():
    # Create a DHT22 device for each configured pin
    dht_devices = {label: adafruit_dht.DHT22(pin) for label, pin in SENSOR_PINS.items()}
    try:
        while True:
            for label, dht_device in dht_devices.items():
                temperature, humidity = read_sensor(dht_device)
                if temperature is not None:
                    LOGGER.info("Sensor %s: %.1fC %.1f%%", label, temperature, humidity)
            time.sleep(5)
    except KeyboardInterrupt:
        LOGGER.info("Station shutting down")
    finally:
        # Close each sensor to release the underlying hardware
        for dht_device in dht_devices.values():
            dht_device.exit()


if __name__ == "__main__":
    main()

# ADC reading loop for a Raspberry Pi using an ADS1x15 ADC
# Reads a single channel and prints it to standard output
import time
import sys
import logging

logging.basicConfig(level=logging.INFO)
LOGGER = logging.getLogger("adc_reader")

ADC_ADDRESS = 0x48
ADC_GAIN = 1
ADC_SAMPLES = 1
ADC_CHANNEL = 0


def open_adc(address):
    """Open the ADS1x15 ADC at the given I2C address."""
    # Import inside the function so the module can run without hardware
    from adafruit_ads1x15 import ADS1x15
    try:
        return ADS1x15(address)
    except OSError as error:
        LOGGER.error("ADC not found: %s", error)
        sys.exit(1)


def read_channel(adc_device, channel_index):
    """Read a single channel from the ADC and return its value."""
    # Perform one conversion and return the result
    return adc_device.read_adc(channel_index, gain=ADC_GAIN)


def is_valid_reading(reading_value):
    """Return True when the ADC reading is within a plausible range."""
    # Reject out-of-range values that indicate a wiring fault
    return 0 <= reading_value <= 32767


def main():
    """Continuously sample the ADC and print each reading."""
    adc_device = open_adc(ADC_ADDRESS)
    try:
        while True:
            reading_value = read_channel(adc_device, ADC_CHANNEL)
            if is_valid_reading(reading_value):
                print("ADC reading:", reading_value)
            else:
                LOGGER.warning("Invalid ADC reading: %s", reading_value)
            time.sleep(0.5)
    except KeyboardInterrupt:
        LOGGER.info("Stopping ADC reader")
    finally:
        # Release the ADC device on exit
        adc_device.close()


if __name__ == "__main__":
    main()

import time
import board
import adafruit_dht

# GPIO pins wired to DHT22 sensors on the Raspberry Pi
DHT_PINS = [board.D4, board.D17, board.D27]

def read_dht22(dht_device):
    """Read temperature and humidity from a DHT22 sensor."""
    # Attempt a single measurement from the DHT22 sensor
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        return temperature, humidity
    except RuntimeError as sensor_error:
        # Sensor not ready or other runtime failure
