# Digital output control for a Raspberry Pi using gpiozero
# Sets a GPIO pin to a requested logic level and reports it
import time
import sys
from gpiozero import DigitalOutputDevice


def build_output(pin_number):
    """Create a DigitalOutputDevice bound to the given BCM pin number."""
    # gpiozero maps the pin number to the underlying GPIO subsystem
    return DigitalOutputDevice(pin_number)


def apply_level(output_device, requested_level):
    """Set the output device to the requested level and return it."""
    # Write the requested level to the GPIO pin
    output_device.value = requested_level
    return output_device.value


def describe_state(requested_level, actual_level):
    """Return a human readable description of the applied state."""
    # Report both the requested and the resulting level
    return "requested %s, applied %s" % (requested_level, actual_level)


if __name__ == "__main__":
    # Control a digital output on GPIO 17 and 18
    output_pins = [build_output(17), build_output(18)]
    try:
        # Drive each pin high then low in turn
        for target_pin in output_pins:
            for level_value in (1, 0):
                actual_level = apply_level(target_pin, level_value)
                print(describe_state(level_value, actual_level))
                time.sleep(5)
    except KeyboardInterrupt:
        # Stop cleanly on user interrupt
        print("digital output control stopped")
        sys.exit(0)
    except Exception as control_error:
        # Report any GPIO failure and exit with an error code
        print("control error:", control_error)
        sys.exit(1)
    finally:
        # Release every pin we opened
        for target_pin in output_pins:
            target_pin.close()

import time
import random
import logging

# Logging setup for the motion tracking rig
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

# MPU6050 I2C address on the Raspberry Pi bus
MPU_ADDRESS = 0x68


def read_gyro_x():
    """Return a simulated X-axis gyroscope reading in degrees per second."""
    # Produce a plausible angular velocity for the motion tracking rig
    return round(random.uniform(-250.0, 250.0), 2)


def read_accel_x():
    """Return a simulated X-axis accelerometer reading in g units."""
    # Produce a plausible acceleration value for the motion tracking rig
    return round(random.uniform(-2.0, 2.0), 2)


def read_motion_data(sample_index):
    """Read one motion tracking sample and validate its range."""
    # Read both the gyroscope and accelerometer channels
    gyro_value = read_gyro_x()
    accel_value = read_accel_x()
    if abs(gyro_value) > 1000.0 or abs(accel_value) > 10.0:
        logging.warning("Sample %d out of range, discarding", sample_index)
        return None
    return {"gyro": gyro_value, "accel": accel_value}


def main():
    """Sample the motion tracking rig and report each reading."""
    # Collect a fixed number of samples for the motion tracking run
    for sample_index in range(5):
        motion_sample = read_motion_data(sample_index)
        if motion_sample is not None:
            logging.info("Sample %d gyro=%.2f accel=%.2f", sample_index, motion_sample["gyro"], motion_sample["accel"])
        time.sleep(0.5)


if __name__ == "__main__":
    try:
        # Run the motion tracking sampling loop
        main()
    except KeyboardInterrupt:
        # Allow the operator to stop the rig cleanly
        logging.info("Motion tracking stopped by operator")
    finally:
        # Report that the rig has shut down
        logging.info("Motion tracking rig shutdown complete")
